<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\ValueObject\Accessor\UserConsentPurposesIpAddressAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserConsentPurposesIpAddressAccessor trait.
 *
 * Covers null default, string/VO assignment via withIpAddress,
 * getIpAddress/ipAddress accessors, and isIpAddressChanged with/without original.
 */
class UserConsentPurposesIpAddressAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withIpAddress creates a new instance with the IpAddress set
     * from a string value, and getIpAddress returns the primitive string.
     */
    public function testWithIpAddressFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentPurposesIpAddressAccessorUnitTest();

        // Act
        $result = $holder->withIpAddress('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getIpAddress());
    }
    /**
     * Asserts that withipAddress has access to the value object
     * from a string value, and getIpAddress returns the primitive string.
     */
    public function testWithIpAddressFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentPurposesIpAddressAccessorUnitTest();

        // Act
        $result = $holder->withIpAddress('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->ipAddress()->value());
    }
    public function testChangedIpAddress(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentPurposesIpAddressAccessorUnitTest();
        $original = $holder->withIpAddress('one');
        $same = $holder->withIpAddress('one');
        $modified = $holder->withIpAddress('other');

        // Act
        $unchanged = $holder->isIpAddressChanged();
        $withSame = $original->isIpAddressChanged($same);
        $withDiferent = $original->isIpAddressChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserConsentPurposesIpAddressAccessorUnitTest
{
    use UserConsentPurposesIpAddressAccessor;
}
